import {useState} from 'react'
import {LanguageSelection} from '@github-ui/code-scanning-shared/components/LanguageSelection'
import {RunnerType, type RunnerLabelType} from '@github-ui/code-scanning-shared/components/RunnerType'
import {useCSRFToken} from '@github-ui/use-csrf-token'
import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {CheckIcon} from '@primer/octicons-react'
import {
  BranchName,
  Button,
  Heading,
  Link,
  RelativeTime,
  ActionList,
  ActionMenu,
  Breadcrumbs,
  Label,
} from '@primer/react'

import styles from './DefaultSetup.module.css'

export interface DefaultSetupPayload {
  securityAnalysisUrl: string
  querySuitesDocumentationUrl: string
  taintedDataDocumentationUrl: string
  customBuildDocumentationUrl: string
  codeqlLanguagesDocumentationUrl: string
  defaultBranch: string
  protectedBranchesUrl: string
  formUrl: string
  formMethod: string
  isDefaultSetupEnabled: boolean
  selectableLanguages: string[]
  selectedLanguages: string[]
  selectedQuerySuite: string
  recommendedQuerySuite: string
  querySuiteOptions: Array<{label: string; value: string; description: string}>
  selectedThreatModel: string
  hasMacOsRunner: boolean
  nextScheduledRunAt: string | null
  isRepoActive: boolean
  onlyLabeledRunners: boolean
  runnerLabel: string | null
  availableRunnerLabels: string[]
}

const threatModelOptions: Array<{label: string; value: string; description: string}> = [
  {
    label: 'Remote sources',
    value: 'remote',
    description: 'For applications that do not trust data from remote sources such as the network',
  },
  {
    label: 'Remote and local sources',
    value: 'remote_and_local',
    description: 'For applications that do not trust data from local sources such as files or CLI commands',
  },
]

export function DefaultSetup() {
  const payload = useRoutePayload<DefaultSetupPayload>()
  const initialQuerySuite = payload.selectedQuerySuite
  const initialThreatModel = payload.selectedThreatModel
  const initialRunnerLabel = payload.runnerLabel

  const csrf = useCSRFToken(payload.formUrl, payload.formMethod)

  const submitButtonText = payload.isDefaultSetupEnabled ? 'Save changes' : 'Enable CodeQL'

  const showScheduleRow = !payload.isDefaultSetupEnabled || payload.isRepoActive

  const [selectedQuerySuite, setSelectedQuerySuite] = useState(initialQuerySuite)

  const querySuiteOptionElements = []
  for (const suite of payload.querySuiteOptions) {
    const value = suite.value
    const label = suite.label
    const description = suite.description

    let recommendedLabel = <></>
    if (payload.recommendedQuerySuite === value) {
      recommendedLabel = <Label variant="accent">Recommended</Label>
    }

    querySuiteOptionElements.push(
      <ActionList.Item key={value} onSelect={() => setSelectedQuerySuite(value)}>
        {label} {recommendedLabel}
        <ActionList.LeadingVisual>{value === selectedQuerySuite && <CheckIcon />} </ActionList.LeadingVisual>
        <ActionList.Description variant="block">{description}</ActionList.Description>
      </ActionList.Item>,
    )
  }

  const querySuiteActionMenuLabel = payload.querySuiteOptions.find(
    querySuiteOption => querySuiteOption.value === selectedQuerySuite,
  )?.label

  const [selectedThreatModel, setSelectedThreatModel] = useState(initialThreatModel)

  const threatModelOptionElements = []
  for (const suite of threatModelOptions) {
    const value = suite.value
    const label = suite.label
    const description = suite.description

    threatModelOptionElements.push(
      <ActionList.Item key={value} onSelect={() => setSelectedThreatModel(value)}>
        {label}
        <ActionList.LeadingVisual>{value === selectedThreatModel && <CheckIcon />} </ActionList.LeadingVisual>
        <ActionList.Description variant="block">{description}</ActionList.Description>
      </ActionList.Item>,
    )
  }

  const threatModelActionMenuLabel = threatModelOptions.find(
    threatModelOption => threatModelOption.value === selectedThreatModel,
  )?.label

  // runner state and UI are managed by RunnerType component. DefaultSetup only
  // needs to know whether the chosen runner selection is valid for submit.
  const [runnerLabelValid, setRunnerLabelValid] = useState<boolean>(
    !initialRunnerLabel || payload.availableRunnerLabels.includes(initialRunnerLabel || ''),
  )

  function handleRunnerChange(change: {runnerType: RunnerLabelType; runnerLabel: string}) {
    const valid = change.runnerType === 'standard' || payload.availableRunnerLabels.includes(change.runnerLabel)
    setRunnerLabelValid(valid)
  }

  return (
    <form noValidate action={payload.formUrl} method="post" data-testid="default-setup-form">
      {
        // eslint-disable-next-line github/authenticity-token
        <input type="hidden" name="authenticity_token" value={csrf} />
      }
      <input type="hidden" name="_method" value={payload.formMethod} autoComplete="off" />
      <div className={styles.pageHeaderContainer}>
        <Breadcrumbs className="mb-3">
          <Breadcrumbs.Item href={payload.securityAnalysisUrl}>Code security</Breadcrumbs.Item>
          <Breadcrumbs.Item selected>CodeQL default configuration</Breadcrumbs.Item>
        </Breadcrumbs>
        <Heading as="h1" className={styles.pageTitle} data-testid="page-title">
          CodeQL default configuration
        </Heading>
      </div>

      <LanguageSelection
        codeqlLanguagesDocumentationUrl={payload.codeqlLanguagesDocumentationUrl}
        hasMacOsRunner={payload.hasMacOsRunner}
        selectableLanguages={payload.selectableLanguages}
        selectedLanguages={payload.selectedLanguages}
        customBuildDocumentationUrl={payload.customBuildDocumentationUrl}
      />

      {/* Query Suite Elements */}
      <div className={styles.sectionHeaderContainer}>
        <Heading as="h2" className={styles.sectionTitle}>
          Scan settings
        </Heading>
        <span className={styles.sectionFieldDescription}>
          Adjust the CodeQL scanning strategy to suit the needs of this application
        </span>
      </div>
      <input type="hidden" name="config[query_suite]" value={selectedQuerySuite} />
      <div className={styles.settingsGroupContainer}>
        <div className={styles.settingRow}>
          <RunnerType
            onlyLabeledRunners={payload.onlyLabeledRunners}
            availableRunnerLabels={payload.availableRunnerLabels}
            initialRunnerType={undefined}
            initialRunnerLabel={initialRunnerLabel}
            productName="Default setup"
            onChange={handleRunnerChange}
          />
        </div>

        <div className={styles.settingRowWithTopBorder} data-testid="query-suite-setting-row">
          <div>
            <span className={styles.sectionFieldLabel}>Query suite</span>
            <span className={styles.sectionFieldDescription}>
              Select the{' '}
              <Link href={payload.querySuitesDocumentationUrl} target="_blank" inline>
                group of CodeQL queries
              </Link>{' '}
              to run against your code
            </span>
          </div>
          <ActionMenu>
            <ActionMenu.Button data-testid="query-suite-action-menu-label">
              {querySuiteActionMenuLabel}
            </ActionMenu.Button>
            <ActionMenu.Overlay width="medium">
              <ActionList showDividers>{querySuiteOptionElements}</ActionList>
            </ActionMenu.Overlay>
          </ActionMenu>
        </div>

        <input type="hidden" name="config[threat_model]" value={selectedThreatModel} />
        <div className={styles.settingRowWithTopBorder} data-testid="threat-model-setting-row">
          <div>
            <span className={styles.sectionFieldLabel}>Threat model</span>
            <span className={styles.threatModelDescription}>
              Select the sources of{' '}
              <Link inline href={payload.taintedDataDocumentationUrl} target="_blank">
                tainted data
              </Link>{' '}
              that may pose a risk to this application.
            </span>
          </div>
          <ActionMenu>
            <ActionMenu.Button data-testid="threat-model-action-model-label">
              {threatModelActionMenuLabel}
            </ActionMenu.Button>
            <ActionMenu.Overlay width="medium">
              <ActionList showDividers>{threatModelOptionElements}</ActionList>
            </ActionMenu.Overlay>
          </ActionMenu>
        </div>

        <div className={styles.sectionHeaderContainer}>
          <Heading as="h2" className={styles.sectionTitle}>
            Scan events
          </Heading>
          <span className={styles.sectionFieldDescription}>These events will trigger a new scan.</span>
        </div>
        <div className={styles.settingsGroupContainer}>
          <div className={styles.scanEventRow}>
            <span className={styles.scanEventLabel}>On push and pull requests to</span>
            <span className={styles.scanEventDetails}>
              <BranchName as="span">{payload.defaultBranch}</BranchName> and{' '}
              <Link inline href={payload.protectedBranchesUrl} data-testid="protected-branches-link">
                protected branches
              </Link>
            </span>
          </div>
          {showScheduleRow && (
            <div className={styles.scanEventRowWithTopBorder}>
              <span className={styles.scanEventLabel}>On a weekly schedule</span>
              {payload.nextScheduledRunAt != null && (
                <span className={styles.scanEventDetails}>
                  Next scan of <BranchName as="span">{payload.defaultBranch}</BranchName>{' '}
                  <RelativeTime
                    datetime={payload.nextScheduledRunAt}
                    threshold="PT0S"
                    hour="numeric"
                    minute="numeric"
                  />
                </span>
              )}
            </div>
          )}
        </div>
        <div className={styles.formActionsContainer}>
          <Button disabled={!runnerLabelValid} type="submit" variant="primary" className={styles.submitButton}>
            {submitButtonText}
          </Button>
          <Button as="a" href={payload.securityAnalysisUrl}>
            Cancel
          </Button>
        </div>
      </div>
    </form>
  )
}

try{ DefaultSetup.displayName ||= 'DefaultSetup' } catch {}